/**
 * M5 Activity: executeNode. Delivers one message to one live node and
 * returns what that node sent, mapped down to {port, msg} (the Workflow,
 * added in M6, resolves destinations itself via the wire graph).
 *
 * Framework-agnostic: no @temporalio/* here. `createExecuteNode` is a plain
 * DI factory - it closes over a bootstrapped flow handle and an installed
 * Capture instance, and returns the exact {flowVersion, nodeId, msg} ->
 * {sends, error?} function M6 hands to Temporal's Activity registration.
 */

"use strict";

function mapSends(sends) {
    return (sends || []).map((s) => ({ port: s.port, msg: s.msg }));
}

function createExecuteNode({ getNode, flowVersion, capture }) {
    return async function executeNode({ flowVersion: requestedFlowVersion, nodeId, msg }) {
        if (requestedFlowVersion !== flowVersion) {
            const error = {
                code: "FLOW_VERSION_MISMATCH",
                nodeId,
                message: `flowVersion mismatch: requested ${requestedFlowVersion}, current ${flowVersion}`,
                sends: []
            };
            return { sends: [], error };
        }

        const node = getNode(nodeId);
        if (!node) {
            const error = {
                code: "NODE_NOT_FOUND",
                nodeId,
                message: `no node found for id ${nodeId}`,
                sends: []
            };
            return { sends: [], error };
        }

        try {
            const result = await capture.around(node, msg, () => node.receive(msg));
            return { sends: mapSends(result.sends) };
        } catch (rejection) {
            const error = {
                code: rejection.timeout ? "NODE_TIMEOUT" : "NODE_ERROR",
                nodeId: rejection.nodeId || nodeId,
                message: rejection.error ? String(rejection.error.message || rejection.error) : "unknown node error",
                sends: mapSends(rejection.sends)
            };
            return { sends: mapSends(rejection.sends), error };
        }
    };
}

module.exports = { createExecuteNode };
